class SystemLog
{
    /**
     * Write a unified system log entry.
     *
     * @param string      $module     Entity module: users, products, categories, customers, orders, purchases, settings, service_templates, auth
     * @param string      $action     Action type: created, updated, deleted, restored, login, logout, blocked_attempt, status_changed, etc.
     * @param int|null    $entityId   ID of the affected entity (user id, product id, etc.)
     * @param string|null $entityName Human-readable name of the entity
     * @param string|null $details    JSON or text description of what changed
     * @param int|null    $userId     Actor user ID (defaults to session user)
     */
    public static function write(string $module, string $action, ?int $entityId = null, ?string $entityName = null, ?string $details = null, ?int $userId = null): void
    {
        // Safety net: never persist a raw base64 image in the log.
        // Controllers should log a picture name / "[image]" placeholder, but if any
        // data: URI slips through, collapse it so the log stays readable.
        if ($details !== null && $details !== '') {
            $details = preg_replace('#data:[^"]*?;base64,[^"]*#i', '[image]', $details);
        }

        try {
            $db = Database::getConnection();



            $actorId = $userId ?? ($_SESSION['user_id'] ?? null);
            $username = null;
            if ($actorId) {
                $stmt = $db->prepare('SELECT username FROM users WHERE id = :id LIMIT 1');
                $stmt->execute(['id' => $actorId]);
                $row = $stmt->fetch();
                $username = $row ? $row['username'] : null;
            }

            $stmt = $db->prepare('INSERT INTO system_logs (user_id, username, module, action, entity_id, entity_name, details, ip_address, created_at) VALUES (:user_id, :username, :module, :action, :entity_id, :entity_name, :details, :ip_address, NOW())');
            $stmt->execute([
                'user_id'     => $actorId,
                'username'    => $username,
                'module'      => $module,
                'action'      => $action,
                'entity_id'   => $entityId,
                'entity_name' => $entityName,
                'details'     => $details,
                'ip_address'  => class_exists('RateLimiter') ? RateLimiter::getClientIp() : ($_SERVER['REMOTE_ADDR'] ?? null),
            ]);

            // Rule 88: Automated 180-Day Log Rolling Retention Protocol

