                } catch (\Throwable $e) {}
            }
        } catch (Throwable $e) {
            // Lazy resilience: if system_logs table is somehow missing, create it outside active transaction and retry once
            try {
                if (!$db->inTransaction()) {
                    $db->exec("CREATE TABLE IF NOT EXISTS system_logs (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        user_id INT NULL,
                        username VARCHAR(255) NULL,
                        module VARCHAR(50) NOT NULL,
                        action VARCHAR(50) NOT NULL,
                        entity_id INT NULL,
                        entity_name VARCHAR(255) NULL,
                        details TEXT NULL,
                        ip_address VARCHAR(45) NULL,
                        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        INDEX idx_module (module),
                        INDEX idx_action (action),
                        INDEX idx_user_id (user_id),
                        INDEX idx_created_at (created_at),
                        INDEX idx_user_action_created (user_id, action, created_at),
                        INDEX idx_module_created (module, created_at),
                        INDEX idx_module_entity (module, entity_id),
                        INDEX idx_entity_id (entity_id),
                        INDEX idx_action_created (action, created_at),
                        INDEX idx_ip_created (ip_address, created_at)
                    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

                    $stmt = $db->prepare('INSERT INTO system_logs (user_id, username, module, action, entity_id, entity_name, details, ip_address, created_at) VALUES (:user_id, :username, :module, :action, :entity_id, :entity_name, :details, :ip_address, NOW())');
                    $stmt->execute([
                        'user_id'     => $actorId,
                        'username'    => $username,
                        'module'      => $module,
                        'action'      => $action,
                        'entity_id'   => $entityId,
                        'entity_name' => $entityName,
                        'details'     => $details,
                        'ip_address'  => class_exists('RateLimiter') ? RateLimiter::getClientIp() : ($_SERVER['REMOTE_ADDR'] ?? null),
                    ]);
                }
            } catch (Throwable $ignored) {}
        }
